// Package widgetcatalog turns the widget's PO translations into the
// JavaScript table its translator reads when the owner picks a language
// other than the desktop's (KDE's i18n always follows the session, SPECS
// §8.3). It is a build tool: nothing at run time uses it.
package widgetcatalog

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"slices"
	"strconv"
	"strings"
)

// Header starts the generated file.
const Header = "// Generated by `go run ./cmd/widget-translations` from translate/*.po; do not edit.\n.pragma library\n\n"

// Build reads every <language>.po of dir and returns translations.js:
// `var table = { "<language>": { "<msgid>": "<msgstr>" or ["<one>",
// "<other>"] } };` with untranslated and fuzzy entries left out.
func Build(dir string) ([]byte, error) {
	paths, err := filepath.Glob(filepath.Join(dir, "*.po"))
	if err != nil {
		return nil, err
	}
	slices.Sort(paths)
	table := map[string]map[string]any{}
	for _, path := range paths {
		entries, err := read(path)
		if err != nil {
			return nil, err
		}
		table[strings.TrimSuffix(filepath.Base(path), ".po")] = entries
	}
	encoded, err := json.MarshalIndent(table, "", " ")
	if err != nil {
		return nil, err
	}
	var out bytes.Buffer
	out.WriteString(Header)
	out.WriteString("var table = ")
	out.Write(encoded)
	out.WriteString(";\n")
	return out.Bytes(), nil
}

// entry is one PO message while it is read.
type entry struct {
	fuzzy   bool
	fields  map[string]string
	current string
}

func read(path string) (map[string]any, error) {
	file, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer file.Close()
	messages := map[string]any{}
	pending := entry{fields: map[string]string{}}
	flush := func() {
		defer func() { pending = entry{fields: map[string]string{}} }()
		msgid, ok := pending.fields["msgid"]
		if !ok || msgid == "" || pending.fuzzy {
			return
		}
		if _, plural := pending.fields["msgid_plural"]; plural {
			forms := []string{pending.fields["msgstr[0]"], pending.fields["msgstr[1]"]}
			if forms[0] != "" && forms[1] != "" {
				messages[msgid] = forms
			}
			return
		}
		if text := pending.fields["msgstr"]; text != "" {
			messages[msgid] = text
		}
	}
	scanner := bufio.NewScanner(file)
	for line := 1; scanner.Scan(); line++ {
		text := strings.TrimSpace(scanner.Text())
		switch {
		case text == "":
			flush()
		case strings.HasPrefix(text, "#,"):
			pending.fuzzy = pending.fuzzy || strings.Contains(text, "fuzzy")
		case strings.HasPrefix(text, "#"):
		case strings.HasPrefix(text, `"`):
			value, err := strconv.Unquote(text)
			if err != nil || pending.current == "" {
				return nil, fmt.Errorf("%s:%d: a stray string", path, line)
			}
			pending.fields[pending.current] += value
		default:
			keyword, quoted, found := strings.Cut(text, " ")
			value, err := strconv.Unquote(quoted)
			if !found || err != nil {
				return nil, fmt.Errorf("%s:%d: %q is not a PO line", path, line, text)
			}
			pending.current = keyword
			pending.fields[keyword] = value
		}
	}
	flush()
	return messages, scanner.Err()
}
